var a=[{title:`Parti dallo scopo`,text:`Per la forma fisica generale, scegli un mix che riesci a gestire di squat o affondi, hinge, spinte, trazioni e lavoro per il tronco. Per la forza, metti per primi gli schemi e gli esercizi in cui produrre più forza conta. Per il condizionamento, aggiungi attività costante o a intervalli adatta al tuo livello. Un esercizio che sembra impressionante ma non serve al tuo obiettivo ha poco valore particolare.`},{title:`Abbina la complessità all’abilità`,text:`Un rematore alla macchina con appoggio può allenare la schiena di un principiante meglio di una versione instabile con pesi liberi. Un goblet squat può essere più facile da imparare di uno squat pesante con bilanciere sulla schiena. Pesi liberi, macchine, elastici e corpo libero sono tutti modi validi per aggiungere resistenza, e la position stand ACSM 2026 non ha indicato un tipo di attrezzatura come il migliore per tutti.`},{title:`Il tuo spazio e il tuo comfort`,text:`Controlla di avere abbastanza spazio sul pavimento e altezza libera sopra la testa, una superficie sicura e attrezzatura installata correttamente. Se devi contenere rumore o impatto, scegli step-up o marcia al posto dei salti. Se un’articolazione è a disagio, riduci il carico o il range oppure passa a uno schema che ti va bene. Se il dolore persiste, chiedi consiglio a un medico o a un fisioterapista.`},{title:`Mantieni stabili alcuni esercizi`,text:`Se cambi gli esercizi a ogni sessione, è difficile capire se stai migliorando. Mantieni alcuni movimenti di riferimento abbastanza a lungo da costruire abilità e confrontare i tuoi numeri, poi ruotali quando cambiano la tua disponibilità, le preferenze o il comfort oppure raggiungi un plateau. La varietà può mantenere vivo il tuo interesse, ma da sola non fa funzionare meglio l’allenamento.`},{title:`Usare TrainUp`,text:`Il tuo piano usa solo esercizi adatti alla tua attrezzatura, al tuo spazio, al soffitto, alla superficie, ai limiti su salti e rumore, alle tue limitazioni, al tuo livello e alla tua coordinazione. Se nessun piano è adatto, TrainUp ti dice quale impostazione lo blocca. In Esplora puoi cercare, filtrare per categoria o attivare il filtro «Solo quelli adatti a me», e ogni pagina di esercizio mostra il suo schema di movimento e i muscoli.`}];var t=[{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Mayo Clinic: pesi liberi e macchine a confronto`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`NSCA: sicurezza e fondamenti dell’allenamento coi pesi`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var o={sections:a,sources:t};export{o as default,a as sections,t as sources};